import {enhanceTerms} from './terms.js';
import {calcEscape as esc} from './calculator-view.js';
import {IMPORT_FIELDS,readImportFile} from './data-import.js';
export function createDataWorkspace({getProfile,persist,sheetContent,notify,openCalculator,onImport,openForms=()=>{}}){
 let root,documentData=null,filename='',sourceDemo=false;
 async function simulation(operation,extra={}){const response=await fetch('/api/calculator/simulate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation,...extra})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Nie udało się otworzyć symulacji.');return data;}
 function mount(node){root=node;draw();}
 function draw(){
 root.innerHTML=`<div class="case-page-heading"><span class="eyebrow">Dane do Twojej sprawy</span><h1>Dane, dokumenty i połączenia</h1><p>Wczytaj własny dokument lub przećwicz połączenie z systemem. Przed uzupełnieniem kalkulatora zobaczysz źródło i zatwierdzisz konkretne pola.</p></div><div class="case-card-grid"><section class="case-card"><h2>Tożsamość</h2><p>Samo logowanie może przekazać dane tożsamości. Nie udostępnia naszej aplikacji wynagrodzeń, ubezpieczenia, salda konta ani danych drugiego rodzica.</p><p class="data-origin">Tryb konkursowy — symulacja logowania. Nie podawaj hasła, PIN-u ani kodu z aplikacji państwowej.</p><div class="data-actions"><button class="secondary" data-login="mObywatel">mObywatel — symulacja</button><button class="secondary" data-login="login.gov.pl">login.gov.pl — symulacja</button><button class="secondary" data-login="eZUS">eZUS — symulacja</button></div><a href="https://www.gov.pl/web/login" target="_blank" rel="noopener noreferrer">O oficjalnym logowaniu</a></section><section class="case-card"><h2>Dane ubezpieczeniowe ZUS</h2><p>To osobny zakres od tożsamości. Wybierz zestaw demonstracyjny; zaświadczenie o rzeczywistym ubezpieczeniu możesz wczytać poniżej.</p><label class="calc-field"><span>Przykładowa sytuacja</span><select id="data-demo-variant"><option value="employee">Pracownik z ubezpieczeniem</option><option value="business-debt">JDG i zadłużenie</option><option value="uninsured">Brak ubezpieczenia chorobowego</option></select></label><button class="secondary" id="data-demo-fetch">Pokaż przykładowe dane ZUS</button><button class="secondary" id="data-forms">e-ZLA, zadłużenie, eZUS i wnioski</button></section><section class="case-card"><h2>Wczytaj swój dokument</h2><p>PDF, XML potwierdzenia danych ZUS, raport e-ZLA albo plik tekstowy CSV/TXT. Odczyt odbywa się na Twoim urządzeniu; oryginał i identyfikatory nie są wysyłane do serwera ani AI.</p><input type="file" id="data-file" accept=".pdf,.xml,.csv,.txt" aria-label="Wczytaj dokument do kalkulatora"><p id="data-file-status" role="status"></p><details><summary>Jak przygotować dokument?</summary><p>W eZUS zamów potwierdzenie z zakresem ubezpieczenia chorobowego. Najdokładniejszy import zapewnia oryginalny XML; PDF pozwala odczytać tekst i pola formularza. Wybór pliku nie potwierdza jego autentyczności.</p><p>Podstawa składek emerytalnych/rentowych lub zdrowotnych nie zostanie potraktowana jako podstawa zasiłku. W PDF bez jednoznacznych etykiet wskaż właściwe pola ręcznie po odczycie. Skan bez warstwy tekstowej wymaga ręcznego przepisania danych.</p></details><button class="secondary" id="data-sample">Wybierz jawny przykład do przetestowania</button><a href="https://www.zus.pl/baza-wiedzy/o-portalu-pue-/samodzielne-tworzenie-potwierdzen-z-danymi-z-zus/dla-ubezpieczonych" target="_blank" rel="noopener noreferrer">Jak uzyskać potwierdzenie danych ZUS</a></section><section class="case-card"><h2>Pomoc i oficjalne informacje</h2><div class="case-help-links"><a href="https://www.zus.pl/ezus" target="_blank" rel="noopener noreferrer">Otwórz rzeczywisty portal eZUS</a><a href="https://www.zus.pl/swiadczenia/zasilki" target="_blank" rel="noopener noreferrer">ZUS — zasiłki i dokumenty</a><a href="https://www.gov.pl/web/rodzina/urlop-rodzicielski" target="_blank" rel="noopener noreferrer">Ministerstwo Rodziny — urlop rodzicielski</a><a href="https://www.pip.gov.pl/dla-pracodawcow/porady-prawne/rodzicielstwo" target="_blank" rel="noopener noreferrer">Państwowa Inspekcja Pracy — rodzicielstwo</a></div><button class="secondary" id="data-medical">Kontakt z lekarzem</button><button class="secondary" id="data-charity">Bezpłatne wsparcie w szczególnej sytuacji</button><p class="field-help">Rzeczywiste połączenie instytucjonalne wymaga formalnej integracji i uprawnień. Obecne przyciski demonstracyjne nie są produkcyjnym logowaniem.</p></section></div><section class="case-card" id="data-preview-panel" ${documentData?'':'hidden'}></section>`;
 root.querySelectorAll('[data-login]').forEach(b=>b.onclick=()=>login(b.dataset.login));root.querySelector('#data-demo-fetch').onclick=demo;root.querySelector('#data-forms').onclick=openForms;root.querySelector('#data-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const status=root.querySelector('#data-file-status');status.textContent='Odczytujemy dokument lokalnie…';documentData=null;root.querySelector('#data-preview-panel').hidden=true;try{documentData=await readImportFile(file);filename=file.name;sourceDemo=documentData.demo===true;drawPreview();status.textContent='Odczyt zakończony. Sprawdź i zatwierdź pola poniżej.';}catch(error){status.textContent=error.message;}};
 root.querySelector('#data-sample').onclick=()=>{sheetContent('Wybierz przykład PDF','<p>To własne, syntetyczne przykłady testowe. Nie są formularzami ZUS ani danymi konkursowymi.</p><button class="secondary" data-example="pracownik">Pracownik — wynagrodzenie 6000 zł</button><button class="secondary" data-example="bez-ubezpieczenia">Brak ubezpieczenia chorobowego</button>');document.querySelectorAll('[data-example]').forEach(b=>b.onclick=async()=>{try{const response=await fetch('examples/'+b.dataset.example+'.pdf'),blob=await response.blob();documentData=await readImportFile(new File([blob],b.dataset.example+'.pdf',{type:'application/pdf'}));filename=b.dataset.example+'.pdf';sourceDemo=true;document.querySelector('#sheet').close();drawPreview();}catch(e){notify(e.message);}});};
 root.querySelector('#data-medical').onclick=()=>sheetContent('Kontakt z lekarzem','<p>W sprawach zdrowia i dokumentów medycznych skontaktujcie się z lekarzem rodzinnym / POZ albo właściwym specjalistą.</p>'+(getProfile().caseStage==='pregnancy'?'<p>W ciąży możecie omówić potrzebne zaświadczenia z lekarzem prowadzącym.</p>':'')+'<p>ZnanyLekarz pozwala wyszukać terminy wizyty w gabinecie lub konsultacji online. Cenę i rodzaj wizyty sprawdźcie u wybranego lekarza.</p><a class="secondary" href="https://www.znanylekarz.pl/" target="_blank" rel="noopener noreferrer">Przejdź do ZnanyLekarz</a>');
 root.querySelector('#data-charity').onclick=async()=>{try{const rules=await(await fetch('data/calculator-rules.json')).json();sheetContent('Wsparcie w szczególnej sytuacji','<p>Strata, wcześniactwo lub ciężka choroba dziecka — sprawdźcie dostępność bezpłatnej pomocy.</p>'+rules.support.map(s=>`<article class="case-card"><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Informacje o pomocy</a></article>`).join(''));}catch{notify('Nie udało się wczytać kontaktów.');}};
 if(documentData)drawPreview();
 }
 async function login(method){try{const data=await simulation('login',{method});sheetContent(method+' — symulacja',`<p class="calc-notice">Potwierdzenie jest demonstracją, a nie rzeczywistym logowaniem.</p><p>${esc(data.message)}</p><dl class="case-facts"><div><dt>Imię i nazwisko — przykład</dt><dd>${esc(data.identity.name)}</dd></div><div><dt>Data urodzenia — przykład</dt><dd>${esc(data.identity.birthDate)}</dd></div></dl><p>Nie pobrano ubezpieczenia, wynagrodzenia, danych dziecka ani drugiego rodzica. Takie informacje wymagają osobnego uprawnionego źródła.</p><button class="primary" id="identity-apply">Użyj przykładowych danych tożsamości</button>`);document.querySelector('#identity-apply').onclick=()=>{persist({applicantName:data.identity.name,applicantBirthDate:data.identity.birthDate,identityOrigin:'demo'});document.querySelector('#sheet').close();onImport({importFields:[{field:'birthDate',value:data.identity.birthDate}],parent:getProfile().parentRole==='father'?1:0,title:0,demo:true});notify('Wpisano przykładową tożsamość. Dane ubezpieczeniowe są osobnym krokiem.');};}catch(error){notify(error.message);}}
 async function demo(){try{const data=await simulation('insurance',{variant:root.querySelector('#data-demo-variant').value}),p=data.parents[0];documentData={kind:'Symulowane pobranie danych ZUS',suggestions:Object.entries(p).filter(([key,value])=>Object.hasOwn(IMPORT_FIELDS,key)&&value!==undefined).map(([field,value])=>({field,value,record:0,evidence:'Dane syntetyczne z symulacji'})),observed:[],warnings:['Dane przykładowe — nie odczytano rzeczywistego konta ZUS.'],text:''};filename='Zestaw demonstracyjny';sourceDemo=true;drawPreview();}catch(error){notify(error.message);}}
 function drawPreview(){
 const panel=root.querySelector('#data-preview-panel');panel.hidden=false;const d=documentData,records=[...new Set(d.suggestions.map(s=>s.record||0))];
 panel.innerHTML=`<h2>Sprawdź pola przed zastosowaniem</h2><p class="data-origin">${esc(filename)} · ${esc(d.kind)}${sourceDemo?' · DANE PRZYKŁADOWE':''}</p>${d.person?`<p>Osoba w dokumencie: <strong>${esc(d.person)}</strong>. Potwierdź, którego rodzica dotyczą dane.</p><label class="calc-check"><input id="import-person" type="checkbox"><span>To moje dane — wpisz imię i nazwisko do profilu wnioskującego</span></label>`:''}${d.warnings.map(w=>`<p class="field-help">${esc(w)}</p>`).join('')}<div class="calc-fields"><label class="calc-field"><span>Właściciel danych w kalkulatorze</span><select id="import-parent"><option value="0">Matka / opiekun 1</option><option value="1" ${getProfile().parentRole==='father'?'selected':''}>Ojciec / uprawniony opiekun 2</option></select></label><label class="calc-field"><span>Tytuł ubezpieczenia</span><select id="import-title"><option value="0">Główny tytuł</option><option value="1">Dodatkowy tytuł 2</option><option value="2">Dodatkowy tytuł 3</option><option value="3">Dodatkowy tytuł 4</option></select></label><label class="calc-field"><span>Zgłoszenie / dokument w pliku</span><select id="import-record">${(records.length?records:[0]).map(r=>`<option value="${r}">Zestaw ${r+1}</option>`).join('')}</select></label></div><div class="data-preview-wrap"><table class="data-preview"><thead><tr><th>Użyj</th><th>Pole</th><th>Wartość</th><th>Źródło / kontekst</th></tr></thead><tbody id="import-rows"></tbody></table></div><div class="calc-fields"><label class="calc-field"><span>Dodaj pole z treści dokumentu</span><select id="import-manual-field">${Object.entries(IMPORT_FIELDS).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></label><label class="calc-field"><span>Odczytana wartość</span><input id="import-manual-value" maxlength="100"></label></div><button class="secondary" id="import-add-field">Dodaj propozycję do zatwierdzenia</button><p class="field-help">W tytule wpisz employee / business / contract / uninsured; chorobowe compulsory / voluntary / none / unknown. Daty: RRRR-MM-DD, kwoty bez symbolu waluty.</p>${d.observed.map(o=>`<p>${esc(o)}</p>`).join('')}${d.text?`<details><summary>Podgląd odczytanej treści dokumentu</summary><pre class="data-doc-text">${esc(d.text)}</pre></details>`:''}<label class="calc-check"><input id="import-confirm" type="checkbox"><span>Sprawdziłem właściciela, rodzaj wartości i okres. Wybrane pola mogą zastąpić odpowiednie dane w bieżącym formularzu.</span></label><button class="primary" id="import-apply">Zastosuj zaznaczone pola w kalkulatorze</button><p id="import-error" class="calc-error" role="alert" hidden></p>`;
 const rows=()=>{const rec=Number(panel.querySelector('#import-record').value);panel.querySelector('#import-rows').innerHTML=d.suggestions.map((s,index)=>s.record!==rec?'':`<tr><td><input type="checkbox" data-import-select="${index}" aria-label="Zatwierdź ${esc(IMPORT_FIELDS[s.field])}"></td><td>${esc(IMPORT_FIELDS[s.field])}</td><td>${esc(String(s.value))}</td><td>${esc(s.evidence)}</td></tr>`).join('');};rows();panel.querySelector('#import-record').onchange=rows;
 panel.querySelector('#import-add-field').onclick=()=>{const field=panel.querySelector('#import-manual-field').value,value=panel.querySelector('#import-manual-value').value.trim();if(!value)return;d.suggestions.push({field,value,evidence:'Ręczny odczyt z dokumentu — użytkownik potwierdza',record:Number(panel.querySelector('#import-record').value)});rows();};
 panel.querySelector('#import-apply').onclick=()=>{const error=panel.querySelector('#import-error');try{if(!panel.querySelector('#import-confirm').checked)throw new Error('Potwierdź sprawdzenie pochodzenia i znaczenia danych.');const fields=[...panel.querySelectorAll('[data-import-select]:checked')].map(c=>d.suggestions[Number(c.dataset.importSelect)]);if(!fields.length)throw new Error('Zaznacz pola, które chcesz zastosować.');if(panel.querySelector('#import-person')?.checked)persist({applicantName:d.person,identityOrigin:sourceDemo?'demo':'manual'});onImport({importFields:fields,parent:Number(panel.querySelector('#import-parent').value),title:Number(panel.querySelector('#import-title').value),demo:sourceDemo});notify('Zastosowano zatwierdzone pola. Pozostałe dane formularza zachowano.');}catch(e){error.hidden=false;error.textContent=e.message;}};
 enhanceTerms(panel);
 panel.scrollIntoView({block:'start',behavior:'smooth'});
 }
 return {mount};
}
